revoke execute on function public._au_tpl_vis(uuid, public.au_templates) from authenticated;
create index if not exists au_templates_event on public.au_templates(event_code);
create index if not exists au_templates_org on public.au_templates(org_id);
create index if not exists au_rules_template on public.au_rules(template_id) where template_id is not null;

