insert into public.au_templates(code,name,description,goal,category,section,event_code,risk,def,params) values
('fin.overdue_claim','مطالبة أولياء الأمور بالمتأخرات','يطالب ولي أمر كل طالب تجاوزت متأخراته المبلغ المحدد، ثم يعيد التحقق بعد مدة ويذكّر إن بقي المبلغ، وينتهي تلقائيًا عند السداد.','متابعة التحصيل دون تدخل يدوي يومي','المالية والمحاسبة','student_finance','ds.student_accounts','medium','{"schedule": {"type": "daily", "at": "07:00", "quiet": false}, "params": {"year": "current", "term": "all", "fee_kind": "all", "repeat": "once"}, "when": {"var": "overdue", "op": "gt", "value": "$p:amount"}, "steps": [{"type": "notify", "key": "claim", "title": "مطالبة رسوم: {{student_name}}", "body": "نود تذكيركم بوجود مبلغ متأخر قدره {{overdue}} ريال على الطالب {{student_name}} في {{school_name}} للعام {{year_name}}.", "recipients": ["guardian"], "channels": ["internal"]}, {"type": "wait", "minutes": "$m:wait"}, {"type": "if", "when": {"var": "overdue", "op": "gt", "value": "$p:amount"}, "then": [{"type": "reminder", "key": "again", "title": "تذكير بالمطالبة: {{student_name}}", "body": "ما زال المبلغ المتأخر {{overdue}} ريال قائمًا على الطالب {{student_name}}.", "recipients": ["guardian"], "channels": ["internal"]}], "else": [{"type": "stop"}]}]}'::jsonb,'[{"key": "amount", "label": "الحد الأدنى للمتأخرات", "type": "number", "default": 2000, "min": 1, "max": 1000000, "unit": "ريال"}, {"key": "wait", "label": "مدة الانتظار قبل إعادة التحقق", "type": "days", "default": 3, "min": 1, "max": 60, "unit": "يوم"}]'::jsonb),
('fin.overdue_escalate','تصعيد المتأخرات إلى محاسب المدرسة','بعد إشعار ولي الأمر وانتظار المدة المحددة، يُصعَّد الطالب الذي ما زال مطابقًا إلى المحاسب المسؤول عن المدرسة.','عدم بقاء المتأخرات الكبيرة دون متابعة بشرية','المالية والمحاسبة','student_finance','ds.student_accounts','medium','{"schedule": {"type": "daily", "at": "07:00", "quiet": false}, "params": {"year": "current", "term": "all", "fee_kind": "all", "repeat": "once"}, "when": {"var": "overdue", "op": "gt", "value": "$p:amount"}, "steps": [{"type": "notify", "key": "claim", "title": "مطالبة رسوم: {{student_name}}", "body": "المبلغ المتأخر {{overdue}} ريال — {{school_name}}.", "recipients": ["guardian"], "channels": ["internal"]}, {"type": "wait", "minutes": "$m:wait"}, {"type": "if", "when": {"var": "overdue", "op": "gt", "value": "$p:amount"}, "then": [{"type": "escalate", "title": "متأخرات قائمة: {{student_name}} ({{overdue}} ريال)", "groups": [{"by": "record", "code": "school_accountant"}]}], "else": [{"type": "stop"}]}]}'::jsonb,'[{"key": "amount", "label": "الحد الأدنى للمتأخرات", "type": "number", "default": 5000, "min": 1, "max": 1000000, "unit": "ريال"}, {"key": "wait", "label": "مدة الانتظار قبل التصعيد", "type": "days", "default": 7, "min": 1, "max": 90, "unit": "يوم"}]'::jsonb),
('fin.balances_report','تقرير أرصدة الطلاب الأسبوعي','تقرير أسبوعي مجمّع بأرصدة الطلاب المتبقية لكل مدرسة، يُشارك مع المحاسب المسؤول ومدير المدرسة دون إرسال رسائل لأولياء الأمور.','رؤية أسبوعية للتحصيل','المالية والمحاسبة','student_finance','ds.student_accounts','low','{"mode": "batch", "schedule": {"type": "weekly", "dow": 0, "at": "07:00", "quiet": false}, "params": {"year": "current", "term": "all", "fee_kind": "all"}, "steps": [{"type": "report", "key": "bal", "title": "أرصدة الطلاب الأسبوعية", "source": "ds.student_accounts", "fields": ["student_name", "school_name", "net", "paid", "remaining", "overdue"], "share": [{"by": "record", "code": "school_accountant"}, {"by": "role", "role": "principal"}], "notify": true}]}'::jsonb,'[]'::jsonb),
('att.repeated','متابعة الغياب المتكرر','عند بلوغ غياب الطالب خلال 30 يومًا العدد المحدد يُشعَر المرشد الطلابي ووكيل المدرسة لمتابعة الحالة.','التدخل المبكر في حالات الغياب','الشؤون التعليمية والحضور','attendance','att.student.repeated','low','{"schedule": {"type": "daily", "at": "07:00", "quiet": false}, "when": {"var": "absences_30d", "op": "gte", "value": "$p:abs"}, "steps": [{"type": "notify", "title": "غياب متكرر لطالب", "body": "بلغ غياب الطالب {{absences_30d}} يومًا خلال 30 يومًا.", "recipients": ["counselor", "vice"]}]}'::jsonb,'[{"key": "abs", "label": "عدد أيام الغياب خلال 30 يومًا", "type": "number", "default": 5, "min": 2, "max": 30, "unit": "يوم"}]'::jsonb),
('att.weekly_report','تقرير الحضور الأسبوعي','تقرير أسبوعي لحضور وغياب وتأخر الطلاب لكل مدرسة، يُحفظ PDF وExcel ويُتاح لمدير المدرسة.','تقرير حضور جاهز كل أسبوع','الأنشطة والتقارير','attendance','ds.api.students','low','{"mode": "batch", "schedule": {"type": "weekly", "dow": 0, "at": "07:00", "quiet": false}, "steps": [{"type": "report", "key": "att", "title": "تقرير الحضور الأسبوعي", "source": "rep.attendance_week", "share": [{"by": "role", "role": "principal"}], "notify": true}]}'::jsonb,'[]'::jsonb),
('adm.incomplete','متابعة طلبات التسجيل غير المكتملة','يذكّر شؤون الطلاب بطلبات التسجيل المفتوحة التي تجاوزت مدة الانتظار المحددة.','عدم تأخر الرد على طلبات التسجيل','التسجيل والقبول','admissions','ds.api.admissions','low','{"schedule": {"type": "daily", "at": "07:00", "quiet": false}, "when": {"all": [{"var": "open", "op": "eq", "value": true}, {"var": "days_waiting", "op": "gte", "value": "$p:days"}]}, "steps": [{"type": "notify", "title": "طلب تسجيل ينتظر: {{student_name}}", "body": "طلب التسجيل {{ref}} مفتوح منذ {{days_waiting}} يومًا.", "recipients": ["student_affairs"]}]}'::jsonb,'[{"key": "days", "label": "أيام الانتظار", "type": "days_n", "default": 5, "min": 1, "max": 60, "unit": "يوم"}]'::jsonb),
('hr.docs_expiry','متابعة انتهاء عقود ووثائق الموظفين','ينبّه مسؤول الموارد البشرية في المدرسة قبل انتهاء العقود والإقامات والوثائق بالمدة المحددة.','تجديد الوثائق قبل انتهائها','الموارد البشرية','hr_documents','ds.hr_docs','low','{"schedule": {"type": "daily", "at": "07:00", "quiet": false}, "when": {"all": [{"var": "days_left", "op": "lte", "value": "$p:days"}, {"var": "renewed", "op": "eq", "value": false}]}, "steps": [{"type": "notify", "title": "وثيقة موظف قاربت الانتهاء: {{employee_name}}", "body": "{{doc_type_name}} تنتهي في {{expires_on}} (متبقٍ {{days_left}} يومًا).", "groups": [{"by": "record", "code": "school_hr"}]}]}'::jsonb,'[{"key": "days", "label": "التنبيه قبل الانتهاء", "type": "days_n", "default": 30, "min": 1, "max": 180, "unit": "يوم"}]'::jsonb),
('hr.contract_letter','طلب خطاب تجديد عقد','ينشئ طلب خطاب تجديد للعقود القريبة من الانتهاء ليُراجع ويُعتمد يدويًا، ولا يُصدر أي خطاب تلقائيًا.','تجهيز خطابات التجديد مبكرًا مع الاعتماد البشري','الموارد البشرية','hr_documents','ds.hr_docs','medium','{"schedule": {"type": "daily", "at": "07:00", "quiet": false}, "params": {"record": "contract"}, "when": {"var": "days_left", "op": "lte", "value": "$p:days"}, "steps": [{"type": "hr_letter", "key": "letter", "kind": "contract_renewal", "note": "طلب تجديد عقد {{employee_name}} (ينتهي {{expires_on}})"}]}'::jsonb,'[{"key": "days", "label": "قبل انتهاء العقد", "type": "days_n", "default": 45, "min": 1, "max": 180, "unit": "يوم"}]'::jsonb),
('hr.leave_pending','تصعيد طلبات الإجازة المتأخرة','يصعّد طلبات الإجازة التي بقيت دون اعتماد أكثر من المدة المحددة.','عدم تعطّل طلبات الإجازة','الموارد البشرية','hr_leave','hr.leave.pending_long','low','{"schedule": {"type": "daily", "at": "07:00", "quiet": false}, "when": {"var": "days_pending", "op": "gte", "value": "$p:days"}, "steps": [{"type": "escalate", "title": "طلب إجازة ينتظر الاعتماد منذ {{days_pending}} يوم", "groups": [{"by": "record", "code": "school_hr"}]}]}'::jsonb,'[{"key": "days", "label": "أيام الانتظار", "type": "days_n", "default": 3, "min": 1, "max": 30, "unit": "يوم"}]'::jsonb),
('docs.org_expiry','متابعة انتهاء وثائق وتراخيص المدارس','ينبّه مسؤول الوثيقة قبل انتهاء التراخيص والشهادات، ثم يصعّد لمدير المدرسة إن لم تُجدَّد قبل الانتهاء بأسبوع.','تجديد التراخيص في وقتها','الوثائق والتراخيص','org_docs','ds.org_docs','low','{"schedule": {"type": "daily", "at": "07:00", "quiet": false}, "when": {"all": [{"var": "has_expiry", "op": "eq", "value": true}, {"var": "days_left", "op": "lte", "value": "$p:days"}]}, "steps": [{"type": "notify", "title": "وثيقة قاربت الانتهاء: {{name}}", "body": "تنتهي في {{expires_on}} (متبقٍ {{days_left}} يومًا).", "groups": [{"by": "record", "code": "doc_owner", "fallback": {"by": "record", "code": "school_docs"}}]}, {"type": "wait_until", "when": {"var": "days_left", "op": "lte", "value": 7}, "every_minutes": 1440, "max_minutes": 525600, "timeout": [{"type": "stop"}]}, {"type": "if", "when": {"var": "days_left", "op": "lte", "value": 7}, "then": [{"type": "escalate", "title": "وثيقة لم تُجدَّد: {{name}}", "groups": [{"by": "role", "role": "principal"}]}], "else": [{"type": "stop"}]}]}'::jsonb,'[{"key": "days", "label": "التنبيه قبل الانتهاء", "type": "days_n", "default": 60, "min": 7, "max": 365, "unit": "يوم"}]'::jsonb),
('tasks.overdue','تصعيد التكليفات المتأخرة','يذكّر المكلَّف بالتكليف المتأخر، ويصعّد لمُسنِد التكليف إذا تجاوز التأخر المدة المحددة.','إنجاز التكليفات في مواعيدها','التكليفات والمهام والطلبات','admin_tasks','adm.task.overdue','low','{"schedule": {"type": "daily", "at": "07:00", "quiet": false}, "when": {"var": "days_overdue", "op": "gte", "value": 1}, "steps": [{"type": "reminder", "title": "تكليف متأخر: {{title}}", "recipients": ["assignee"]}, {"type": "if", "when": {"var": "days_overdue", "op": "gte", "value": "$p:days"}, "then": [{"type": "escalate", "title": "تكليف متأخر {{days_overdue}} يوم: {{title}}", "recipients": ["assigner"]}], "else": [{"type": "stop"}]}]}'::jsonb,'[{"key": "days", "label": "أيام التأخر قبل التصعيد", "type": "days_n", "default": 3, "min": 1, "max": 30, "unit": "يوم"}]'::jsonb),
('requests.stale','متابعة الطلبات الإدارية المتأخرة','يصعّد الطلبات الإدارية التي لم تُعالَج خلال المدة المحددة إلى مدير المدرسة.','عدم تأخر المعاملات الإدارية','التكليفات والمهام والطلبات','admin_requests','adm.request.stale','low','{"schedule": {"type": "daily", "at": "07:00", "quiet": false}, "when": {"var": "days_waiting", "op": "gte", "value": "$p:days"}, "steps": [{"type": "escalate", "title": "طلب إداري ينتظر منذ {{days_waiting}} يوم: {{form_name}}", "recipients": ["principal"]}]}'::jsonb,'[{"key": "days", "label": "أيام الانتظار", "type": "days_n", "default": 3, "min": 1, "max": 30, "unit": "يوم"}]'::jsonb),
('mt.late_followup','متابعة طلبات الصيانة المتأخرة','يذكّر المعالج بطلب الصيانة المتأخر عن موعده، ويصعّد لمسؤول الصيانة في المدرسة عند تجاوز المدة المحددة.','إغلاق طلبات الصيانة في وقتها','صيانة المباني والمرافق','maint_school','ds.maintenance','low','{"schedule": {"type": "daily", "at": "07:00", "quiet": false}, "when": {"all": [{"var": "open", "op": "eq", "value": true}, {"var": "days_late", "op": "gte", "value": 1}]}, "steps": [{"type": "reminder", "title": "طلب صيانة متأخر: {{ref}}", "recipients": ["handler"]}, {"type": "if", "when": {"var": "days_late", "op": "gte", "value": "$p:days"}, "then": [{"type": "escalate", "title": "طلب صيانة متأخر {{days_late}} يوم: {{ref}}", "groups": [{"by": "record", "code": "school_maint"}]}], "else": [{"type": "stop"}]}]}'::jsonb,'[{"key": "days", "label": "أيام التأخر قبل التصعيد", "type": "days_n", "default": 3, "min": 1, "max": 60, "unit": "يوم"}]'::jsonb),
('bus.docs','متابعة رخص وفحص الحافلات وموعد صيانتها','ينبّه مسؤول المركبة قبل انتهاء رخصة الحافلة أو موعد الفحص أو الصيانة الدورية بالمدة المحددة.','عدم تشغيل حافلة بوثائق منتهية','النقل المدرسي وصيانة الحافلات','maint_bus','ds.api.buses','low','{"schedule": {"type": "daily", "at": "07:00", "quiet": false}, "when": {"any": [{"var": "license_expiry_days", "op": "lte", "value": "$p:days"}, {"var": "inspection_date_days", "op": "lte", "value": "$p:days"}, {"var": "next_service_date_days", "op": "lte", "value": "$p:days"}]}, "steps": [{"type": "notify", "title": "موعد قريب للحافلة {{code}}", "body": "الرخصة: {{license_expiry}} — الفحص: {{inspection_date}} — الصيانة: {{next_service_date}}", "groups": [{"by": "record", "code": "bus_owner", "fallback": {"by": "record", "code": "school_transport"}}]}]}'::jsonb,'[{"key": "days", "label": "التنبيه قبل الموعد", "type": "days_n", "default": 30, "min": 1, "max": 180, "unit": "يوم"}]'::jsonb),
('ops.maintenance_report','تقرير تشغيلي بطلبات الصيانة المفتوحة','تقرير أسبوعي مجمّع بطلبات الصيانة المفتوحة لكل مدرسة يُحفظ للمخولين دون إرسال أي رسالة.','متابعة تشغيلية بلا إشعارات','الأنشطة والتقارير','maint_school','ds.maintenance','low','{"mode": "batch", "schedule": {"type": "weekly", "dow": 0, "at": "07:00", "quiet": false}, "when": {"var": "open", "op": "eq", "value": true}, "steps": [{"type": "report", "key": "mt", "title": "طلبات الصيانة المفتوحة", "source": "ds.maintenance", "fields": ["ref", "title", "school_name", "status", "priority", "days_open", "days_late"], "share": [{"by": "record", "code": "school_maint"}, {"by": "role", "role": "principal"}], "notify": false}]}'::jsonb,'[]'::jsonb),
('ops.monthly_tasks_report','تقرير شهري بالتكليفات المفتوحة','تقرير شهري مجمّع بالتكليفات المفتوحة والمتأخرة لكل مدرسة لمدير المدرسة.','متابعة إنجاز التكليفات شهريًا','الأنشطة والتقارير','admin_tasks','ds.admin_tasks','low','{"mode": "batch", "schedule": {"type": "monthly", "day": 1, "at": "07:00", "quiet": false}, "when": {"var": "open", "op": "eq", "value": true}, "steps": [{"type": "report", "key": "tk", "title": "التكليفات المفتوحة", "source": "ds.admin_tasks", "fields": ["title", "assignee_name", "department_name", "due", "days_overdue", "status"], "share": [{"by": "role", "role": "principal"}], "notify": true}]}'::jsonb,'[]'::jsonb);
insert into public.au_template_versions(template_id,version,def,params,note) select id,1,def,params,'الإصدار الأول' from public.au_templates where org_id is null;